/*
 * ===========================================================================
 * 0083  A STRUCTURAL LETTER FOR PERMIT RECORDS ITS OPTION AND ITS SCHEDULE.
 * ===========================================================================
 * GENERATED BY scripts/emit-pl-determination-migration.mjs from this file's
 * head and tail and 0068's own text; do not edit by hand.
 *
 * Operator ruling of 2026-10-22, from the engineer of record's email that day
 * (docs/rulings-2026-10-22.md, section 1), for 254-PL-001:
 *   A  a pass with no conditions;
 *   B  a pass with the condition listed in the letter's schedule, and sealing
 *      refused if the schedule is empty;
 *   C  repairs required.
 *
 * WHY THE DETERMINATION CARRIES IT. A determination is written once, inside
 * eng_record_review_decision (0068), and never changes (0051's trigger), so
 * the option and the schedule have to be on it when it is written; a sealing
 * step reading them later can only read what was recorded. With the rule
 * enforced here, a B with an empty schedule cannot be recorded at all, so no
 * sealing step can ever be handed one. src/lib/structural-letter-verdict.ts is
 * the same rule in code, asked before the decision is sent.
 *
 * WHAT THIS DOES
 *   1. eng_determinations.letter_option (A, B or C, or null) and
 *      letter_conditions (text[], the schedule, in the engineer's words).
 *   2. A check that holds the ruling for 254-PL-001 and keeps both empty for
 *      every other protocol: pass takes A with no conditions or B with at
 *      least one; repairs required takes C with none; revise, site revisit and
 *      decline take no option and no conditions.
 *   3. A trigger refusing a blank condition, which the check cannot see.
 *   4. eng_record_review_decision, 0068's text byte for byte except that the
 *      determination insert carries the two new fields.
 *
 * Every determination already recorded is a 254-RC-001 one with neither
 * field, so it satisfies the check as written. No drop statement. SECURITY
 * INVOKER, search_path pinned, EXECUTE revoked from PUBLIC, anon and
 * authenticated in this file (0073).
 */

/* 1. The option and the schedule, on the determination. */
alter table eng_determinations
  add column if not exists letter_option text check (letter_option in ('A', 'B', 'C')),
  add column if not exists letter_conditions text[] not null default '{}';

comment on column eng_determinations.letter_option is
  'For 254-PL-001, which of the engineer''s three letter sentences: A pass with no conditions, B pass with the conditions in the schedule, C repairs required. Null for every other protocol and for a determination that produces no letter. 0083, operator ruling of 2026-10-22.';
comment on column eng_determinations.letter_conditions is
  'For 254-PL-001 option B, the conditions listed in the letter''s schedule, in the engineer''s words: at least one, none blank. Empty otherwise. 0083.';

/*
 * 2. The ruling, held by the row itself. EVERY COMPARISON GOES THROUGH
 * coalesce: `letter_option = 'A'` is null when the option is null, and a CHECK
 * whose expression is null PASSES, so a PL pass with no option would have been
 * recorded. The signing proof's first version caught exactly that; the
 * operator's review of 0081 caught the same trap in a NOT VALID check.
 */
alter table eng_determinations
  add constraint eng_determinations_permit_letter_option_ck check (
    (protocol_document <> '254-PL-001' and letter_option is null and cardinality(letter_conditions) = 0)
    or (
      protocol_document = '254-PL-001' and (
        (determination = 'pass' and coalesce(letter_option, '') = 'A' and cardinality(letter_conditions) = 0)
        or (determination = 'pass' and coalesce(letter_option, '') = 'B' and cardinality(letter_conditions) >= 1)
        or (determination = 'repairs-required' and coalesce(letter_option, '') = 'C' and cardinality(letter_conditions) = 0)
        or (determination not in ('pass', 'repairs-required') and letter_option is null and cardinality(letter_conditions) = 0)
      )
    )
  );

/* 3. A condition is words, never a blank the count would let through. */
create or replace function eng_determination_conditions_are_written()
returns trigger
language plpgsql
set search_path = ''
as $fn$
begin
  if exists (select 1 from unnest(new.letter_conditions) c where c is null or btrim(c) = '') then
    raise exception
      'A condition in the letter''s schedule is the engineer''s words, and one is blank (0083).';
  end if;
  return new;
end;
$fn$;

create trigger eng_determinations_conditions_are_written
  before insert on eng_determinations
  for each row execute function eng_determination_conditions_are_written();

/* 4. The decision, 0068's function with the two fields carried into the determination. */

create or replace function eng_record_review_decision(p jsonb)
returns jsonb
language plpgsql
set search_path = ''
as $fn$
declare
  v_file_id      uuid := (p->>'file_id')::uuid;
  v_actor_id     uuid := (p->>'actor_id')::uuid;
  v_action       text := p->>'action';
  v_expected     text := p->>'expected_status';
  v_target       text := p->>'target_status';
  v_stamp        text := p->>'stamp_column';
  v_note         text := nullif(p->>'note', '');
  v_status       text;
  v_det_id       uuid := null;
  v_det          jsonb := p->'determination';
  v_session      jsonb := p->'session';
  v_credit       jsonb := p->'credit';
  v_log          jsonb := p->'charge_log';
  v_job          jsonb := p->'job';
  v_job_id       bigint := null;
  v_i            integer := 0;
  v_req          text;
begin
  if v_action not in ('seal', 'revisions', 'site_visit', 'repairs', 'refuse') then
    raise exception 'Not a review action: %', v_action;
  end if;

  -- The one check only the database can make: the file has not moved since the
  -- rules were judged. The lock holds it for the rest of this transaction.
  select status into v_status from public.eng_files where id = v_file_id for update;
  if v_status is null then
    raise exception 'That file does not exist.';
  end if;
  if v_status is distinct from v_expected then
    raise exception 'The file moved while this decision was being recorded (it is now %). Nothing was written; decide again.', v_status;
  end if;

  -- The determination and its repair list.
  if v_det is not null and v_det <> 'null'::jsonb then
    insert into public.eng_determinations
      (file_id, protocol_document, determination, relied_on_item_keys, relied_on_evidence_ids, note, engineer_id,
       letter_option, letter_conditions)
    values
      (v_file_id, v_det->>'protocol_document', v_det->>'determination',
       coalesce(array(select jsonb_array_elements_text(v_det->'relied_on_item_keys')), '{}'),
       coalesce(array(select (jsonb_array_elements_text(v_det->'relied_on_evidence_ids'))::uuid), '{}'),
       nullif(v_det->>'note', ''), v_actor_id,
       nullif(v_det->>'letter_option', ''),
       coalesce(array(select jsonb_array_elements_text(coalesce(v_det->'letter_conditions', '[]'::jsonb))), '{}'))
    returning id into v_det_id;

    for v_req in select jsonb_array_elements_text(coalesce(p->'repairs', '[]'::jsonb)) loop
      insert into public.eng_repair_items (file_id, determination_id, sort_order, requirement, raised_by)
      values (v_file_id, v_det_id, v_i, v_req, v_actor_id);
      v_i := v_i + 1;
    end loop;
  end if;

  -- The status move, its stamp, its file event and its audit row. A passing
  -- decision does not move the file: the seal act does (letter-seal.ts).
  if v_target is not null then
    if v_stamp is not null and v_stamp not in
        ('dispatched_at', 'refused_at', 'repairs_required_at', 'evidence_submitted_at', 'sealed_at', 'delivered_at', 'closed_at') then
      raise exception 'Not a status stamp column: %', v_stamp;
    end if;
    update public.eng_files set status = v_target where id = v_file_id;
    if v_stamp is not null then
      execute format('update public.eng_files set %I = now() where id = $1', v_stamp) using v_file_id;
    end if;
    insert into public.eng_file_events (file_id, actor_id, kind, from_status, to_status, body)
    values (v_file_id, v_actor_id, 'status', v_status, v_target, v_note);
    insert into public.eng_audit_events
      (actor_id, actor_email, actor_role, action, entity_type, entity_id, summary, diff, ip, user_agent)
    values
      (v_actor_id, p->>'actor_email', p->>'actor_role', 'file.transition', 'file', v_file_id::text,
       p->>'transition_summary', jsonb_build_object('status', jsonb_build_object('from', v_status, 'to', v_target)),
       p->>'ip', p->>'user_agent');
  end if;

  if v_action = 'refuse' then
    update public.eng_files
       set refused_at = now(), refusal_reason = v_note, refused_by = v_actor_id
     where id = v_file_id;
  end if;
  if v_action in ('revisions', 'site_visit') then
    update public.eng_files set revision_count = revision_count + 1 where id = v_file_id;
  end if;
  if v_action in ('site_visit', 'repairs') then
    update public.eng_files set assigned_tech_id = null where id = v_file_id;
    update public.eng_assignments
       set state = 'withdrawn', responded_at = now()
     where file_id = v_file_id and state = 'accepted';
  end if;

  -- The review clock.
  if v_session is not null and v_session <> 'null'::jsonb then
    update public.eng_review_sessions
       set ended_at = now(), decision = v_action, minutes = (v_session->>'minutes')::integer
     where id = (v_session->>'id')::uuid;
  end if;

  -- The responsible charge log, built by chargeLogRow in TypeScript.
  insert into public.eng_responsible_charge_log
    (engineer_id, decision, file_id, document_id, document_type, property_address, county,
     reviewed_at, review_minutes, revision_count, site_visit, refused, refusal_reason, period, review_session_id)
  values
    (v_actor_id, v_action, v_file_id, nullif(v_log->>'document_id', '')::uuid, v_log->>'document_type',
     v_log->>'property_address', v_log->>'county', now(), nullif(v_log->>'review_minutes', '')::integer,
     coalesce((v_log->>'revision_count')::integer, 0), coalesce((v_log->>'site_visit')::boolean, false),
     v_action = 'refuse', v_log->>'refusal_reason', v_log->>'period',
     nullif(v_session->>'id', '')::uuid);

  -- The credit, the figure productionCreditFor computed from engineer-pay.ts.
  if v_credit is not null and v_credit <> 'null'::jsonb then
    insert into public.eng_production_ledger
      (engineer_id, file_id, review_session_id, decision, amount_cents, period, status, note)
    values
      (v_actor_id, v_file_id, (v_session->>'id')::uuid, v_action, (v_credit->>'amount_cents')::integer,
       v_credit->>'period', 'pending', v_credit->>'note');
  end if;

  -- The decision's own audit row.
  insert into public.eng_audit_events
    (actor_id, actor_email, actor_role, action, entity_type, entity_id, summary, ip, user_agent)
  values
    (v_actor_id, p->>'actor_email', p->>'actor_role', 'review.' || v_action, 'file', v_file_id::text,
     p->>'decision_summary', p->>'ip', p->>'user_agent');

  -- What reaches outside, queued for after commit.
  if v_job is not null and v_job <> 'null'::jsonb then
    insert into public.eng_jobs (kind, payload, idempotency_key, effect_mode)
    values (v_job->>'kind', v_job->'payload', v_job->>'idempotency_key',
            coalesce(v_job->>'effect_mode', 'live'))
    returning id into v_job_id;
  end if;

  return jsonb_build_object('determination_id', v_det_id, 'job_id', v_job_id);
end;
$fn$;

/* 0073's rule for every function added or replaced here, and asserted for the whole schema. */
do $$
declare
  f record;
  open_fns text;
begin
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in ('eng_determination_conditions_are_written', 'eng_record_review_decision')
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
    execute format('grant execute on function %s to service_role', f.sig);
  end loop;

  select string_agg(p.oid::regprocedure::text, ', ') into open_fns
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.proname like 'eng\_%'
    and (has_function_privilege('anon', p.oid, 'EXECUTE')
         or has_function_privilege('authenticated', p.oid, 'EXECUTE'));
  if open_fns is not null then
    raise exception 'eng: after 0083 these are still executable by anon or authenticated: %', open_fns;
  end if;
end;
$$;
